    /// The live gate, [`applicability`], the one entry `measure` calls, reads the
    /// attribution, the mode with its basis, and not the mode: an environment recorded
    /// `host` on `assumed-host` withholds a `needs_vm` check under
    /// `execution-mode-assumed`, quoting the observation; the same `host`, or `vm`, on the
    /// operator's word measures it; a container withholds it under `needs-vm`. Until
    /// 2026-10-15 the first read as the second.
    #[test]
    fn the_live_gate_reads_the_attribution_not_the_mode() {
        use crate::env::{ExecutionMode, ModeBasis, ModeEvidence};
        let check = crate::probe::CORPUS
            .iter()
            .flat_map(|p| p.checks)
            .find(|c| c.id == "noexecstack-enforced")
            .expect("noexecstack-enforced is a check");
        assert!(check.gate.needs_vm, "the check declares needs_vm");
        let observation = "no runtime marker file, no /run/systemd/container, /proc/1/environ \
                           unreadable (permission denied, os error 13), the identity uid map \
                           `0 0 4294967295`, /proc/1/comm is `bash`";
        let mut env = environment_fixture();
        let mut on = |mode: ExecutionMode, basis: ModeBasis| {
            env.execution.mode = mode;
            env.execution.mode_evidence = ModeEvidence {
                basis,
                observed: (mode == ExecutionMode::Container).then_some(mode),
                observation: observation.to_owned(),
            };
            applicability(check, &env, "x86_64")
        };
        let Applicability::Untrustworthy(gating) = on(ExecutionMode::Host, ModeBasis::AssumedHost)
        else {
            panic!("host by default measured a kernel-policy check");
        };
        assert_eq!(gating.rule, gating_rule::EXECUTION_MODE_ASSUMED);
        assert!(gating.reason.contains(observation), "{}", gating.reason);
        for mode in [ExecutionMode::Host, ExecutionMode::Vm] {
            assert!(
                matches!(
                    on(mode, ModeBasis::AssertedButUnobservable),
                    Applicability::Applicable
                ),
                "{mode:?} on the operator's word measures"
            );
        }
        let Applicability::Untrustworthy(gating) =
            on(ExecutionMode::Container, ModeBasis::Measured)
        else {
            panic!("a container measured a kernel-policy check");
        };
        assert_eq!(gating.rule, gating_rule::NEEDS_VM);
    }

    /// `mode_evidence.basis` is an input of the run: `host` by default and an asserted
    /// `host` read the `needs_vm` checks differently, so two runs that differ in the basis
    /// alone digest apart, since their verdicts differ, and the line sits beside the mode's.
    #[test]
    fn the_mode_basis_is_an_input_of_the_run() {
        use crate::env::{ExecutionMode, ModeBasis};
        let mut report = identity_fixture();
        report.environment.execution.mode = ExecutionMode::Host;
        report.environment.execution.mode_evidence.observed = None;
        let digest_on = |report: &mut Report, basis: ModeBasis| {
            report.environment.execution.mode_evidence.basis = basis;
            let identity = inputs_of(report);
            assert!(
                identity
                    .canonical()
                    .contains(&format!("execution.mode_basis={}", basis.as_str())),
                "{}",
                identity.canonical()
            );
            identity.sha256()
        };
        let by_default = digest_on(&mut report, ModeBasis::AssumedHost);
        let asserted = digest_on(&mut report, ModeBasis::AssertedButUnobservable);
        assert_ne!(
            by_default, asserted,
            "the basis alone moves the input digest"
        );
        assert_eq!(
            by_default,
            digest_on(&mut report, ModeBasis::AssumedHost),
            "and the digest is a function of the inputs"
        );
    }

